select
    a.dt,
    count(distinct b.ukey) as user_cnt
from gamelive.dwd_huya_predicting_game_pay_option_detail_d_i a
left join (
  select yyuid,ukey,end_time ,rn 
  from(
    select yyuid,ukey,end_time 
      ,row_number()over(partition by yyuid order by end_time desc) rn
    from gamelive.dwt_huya_session_level 
    where dt between '2024-01-01' and '2026-07-19'
      and length(dt)=10  
      and tag = 'product' 
  )t 
  where rn=1 
) b
on a.uid = b.yyuid
where 
    a.dt between '2026-06-12' and '2026-07-19'
    a.create_pid in (
    10748220,2367547387,1199630339535,1199652774074,294636272,1575250000,2272316519,1199568157971,1867489698,1279518938631,1014447803,1860008570,1531433300,1199526826004,1486343265,500066171,1661091641,1589657344,1509413742,2381472418,1191588902,1199656029798,1677942333,1279515529757,1271256459,1182498550,1199585096447,1636999467,1852594244,1279513816099,1607888466,1259517233171,1199659485620,9284975,20852986,1784500555,1199599175963,1199548593898,103291603,1062203607,1199661106293,1199641333987,1199602377745,1199655480461,1199610004865,1558173124,1279542841394,1259527226795,1199590843647,1199657592299,1199642042189,1199614292524,1199628311699,1199657141334,1279527609081,2373515260,585199800,1239543466013,1239543466014,1001276654
    )
    and a.mode in (4)

